  <style>
    /* ===== Reset & Base ===== */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --red: #C41E3A;
      --red-dark: #A01830;
      --red-light: #FDE8EC;
      --navy: #1B3A5C;
      --navy-light: #2A5A8C;
      --white: #FFFFFF;
      --gray-50: #FAFAFA;
      --gray-100: #F5F5F5;
      --gray-200: #E8E8E8;
      --gray-300: #D0D0D0;
      --gray-500: #888888;
      --gray-700: #555555;
      --gray-900: #1A1A1A;
      --font-heading: 'Segoe UI', system-ui, -apple-system, sans-serif;
      --font-body: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font-body);
      color: var(--gray-900);
      background: var(--white);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    img { max-width: 100%; height: auto; display: block; }
    a { color: inherit; text-decoration: none; }
    ul { list-style: none; }
    button { font: inherit; cursor: pointer; border: none; background: none; }

    h1, h2, h3, h4 { font-family: var(--font-heading); line-height: 1.2; }
    h2 { font-size: clamp(1.75rem, 4vw, 2.5rem); font-weight: 800; color: var(--navy); }
    h3 { font-size: clamp(1.25rem, 3vw, 1.5rem); font-weight: 700; }

    .container { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 1.5rem; }

    .section { padding: 5rem 0; }

    .section-label {
      display: inline-block;
      font-size: 0.8rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: var(--red);
      margin-bottom: 0.75rem;
    }

    .section-title { margin-bottom: 1rem; }

    .section-subtitle {
      font-size: 1.1rem;
      color: var(--gray-700);
      max-width: 640px;
      line-height: 1.7;
    }

    /* ===== Buttons ===== */
    .btn {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0.85rem 1.75rem;
      border-radius: 6px;
      font-weight: 700;
      font-size: 0.95rem;
      transition: background 0.2s, transform 0.15s;
    }
    .btn:active { transform: scale(0.97); }

    .btn-primary {
      background: var(--red);
      color: var(--white);
    }
    .btn-primary:hover { background: var(--red-dark); }

    .btn-outline {
      border: 2px solid var(--white);
      color: var(--white);
    }
    .btn-outline:hover { background: rgba(255,255,255,0.15); }

    .btn-outline-dark {
      border: 2px solid var(--navy);
      color: var(--navy);
    }
    .btn-outline-dark:hover { background: var(--navy); color: var(--white); }

    /* ===== Header ===== */
    .header {
      position: sticky;
      top: 0;
      z-index: 1000;
      background: var(--white);
      border-bottom: 1px solid var(--gray-200);
    }
    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 72px;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 0.6rem;
      font-family: var(--font-heading);
      font-weight: 800;
      font-size: 1.2rem;
      color: var(--navy);
      white-space: nowrap;
    }
    .logo-icon {
      width: 38px;
      height: 38px;
      background: var(--red);
      border-radius: 6px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--white);
      font-size: 1.4rem;
      font-weight: 900;
      line-height: 1;
    }

    .nav { display: flex; align-items: center; gap: 1.5rem; }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 1.5rem;
    }
    .nav-links a {
      font-size: 0.9rem;
      font-weight: 600;
      color: var(--gray-700);
      transition: color 0.2s;
    }
    .nav-links a:hover { color: var(--red); }

    .nav-utility {
      display: flex;
      align-items: center;
      gap: 1rem;
      margin-right: 0.5rem;
      font-size: 0.83rem;
      color: var(--gray-500);
    }
    .nav-utility a { color: var(--gray-500); transition: color 0.2s; }
    .nav-utility a:hover { color: var(--gray-700); }
    .nav-utility .sep { color: var(--gray-300); }

    .btn-header-donate {
      padding: 0.55rem 1.25rem;
      font-size: 0.85rem;
    }

    /* Hamburger */
    .hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      width: 28px;
      padding: 4px 0;
      cursor: pointer;
    }
    .hamburger span {
      display: block;
      height: 2.5px;
      background: var(--navy);
      border-radius: 2px;
      transition: transform 0.3s, opacity 0.2s;
    }
    .hamburger.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
    .hamburger.active span:nth-child(2) { opacity: 0; }
    .hamburger.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

    /* Mobile nav drawer */
    .mobile-nav {
      display: none;
      position: fixed;
      top: 72px;
      left: 0;
      right: 0;
      bottom: 0;
      background: var(--white);
      z-index: 999;
      padding: 2rem 1.5rem;
      flex-direction: column;
      gap: 0.25rem;
      overflow-y: auto;
    }
    .mobile-nav.active { display: flex; }
    .mobile-nav a {
      display: block;
      padding: 0.8rem 0;
      font-size: 1.1rem;
      font-weight: 600;
      color: var(--navy);
      border-bottom: 1px solid var(--gray-100);
    }
    .mobile-nav .mobile-utility {
      margin-top: 1rem;
      padding-top: 1rem;
      border-top: 2px solid var(--gray-200);
      display: flex;
      flex-direction: column;
      gap: 0.5rem;
    }
    .mobile-nav .mobile-utility a {
      font-size: 0.9rem;
      font-weight: 500;
      color: var(--gray-500);
      border: none;
      padding: 0.4rem 0;
    }
    .mobile-nav .btn-header-donate {
      margin-top: 1rem;
      text-align: center;
    }

    /* ===== Hero ===== */
    .hero {
      position: relative;
      background: linear-gradient(135deg, var(--navy) 0%, #0D2338 100%);
      color: var(--white);
      padding: 6rem 0;
      overflow: hidden;
    }
    .hero::before {
      content: '';
      position: absolute;
      top: -50%;
      right: -20%;
      width: 600px;
      height: 600px;
      background: radial-gradient(circle, rgba(196,30,58,0.15) 0%, transparent 70%);
      border-radius: 50%;
    }
    .hero .container { position: relative; z-index: 1; }

    .hero h1 {
      font-size: clamp(2.2rem, 5.5vw, 3.5rem);
      font-weight: 900;
      line-height: 1.1;
      margin-bottom: 1.25rem;
      max-width: 700px;
    }
    .hero p {
      font-size: clamp(1rem, 2vw, 1.2rem);
      color: rgba(255,255,255,0.8);
      max-width: 600px;
      line-height: 1.65;
      margin-bottom: 2rem;
    }
    .hero-ctas { display: flex; gap: 1rem; flex-wrap: wrap; }

    /* ===== Mission ===== */
    .mission {
      background: var(--gray-50);
      border-bottom: 1px solid var(--gray-200);
    }
    .mission blockquote {
      font-size: clamp(1.1rem, 2.5vw, 1.35rem);
      font-weight: 600;
      color: var(--red);
      font-style: italic;
      border-left: 4px solid var(--red);
      padding-left: 1.5rem;
      margin-bottom: 1.5rem;
      max-width: 750px;
    }
    .mission p {
      color: var(--gray-700);
      max-width: 750px;
      line-height: 1.75;
      font-size: 1.02rem;
    }

    /* ===== Impact Stats ===== */
    .impact-stats { background: var(--white); }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 2rem;
      margin-top: 2.5rem;
    }
    .stat-card {
      text-align: center;
      padding: 2rem 1rem;
      background: var(--gray-50);
      border-radius: 12px;
      border: 1px solid var(--gray-200);
      transition: transform 0.2s;
    }
    .stat-card:hover { transform: translateY(-3px); }

    .stat-number {
      font-family: var(--font-heading);
      font-size: clamp(2rem, 4vw, 2.8rem);
      font-weight: 900;
      color: var(--red);
      line-height: 1;
      margin-bottom: 0.5rem;
    }
    .stat-label {
      font-size: 0.95rem;
      color: var(--gray-700);
      font-weight: 600;
    }
    .stat-sub {
      font-size: 0.82rem;
      color: var(--gray-500);
      margin-top: 0.25rem;
    }

    /* ===== Programs Accordion ===== */
    .programs {
      background: var(--gray-50);
      border-top: 1px solid var(--gray-200);
      border-bottom: 1px solid var(--gray-200);
    }

    .accordion { margin-top: 2.5rem; max-width: 850px; }

    .accordion-item {
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: 10px;
      margin-bottom: 0.75rem;
      overflow: hidden;
    }

    .accordion-header {
      width: 100%;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 1.25rem 1.5rem;
      text-align: left;
      font-size: 1.05rem;
      font-weight: 700;
      color: var(--navy);
      transition: background 0.2s;
    }
    .accordion-header:hover { background: var(--gray-50); }

    .accordion-icon {
      width: 32px;
      height: 32px;
      border-radius: 50%;
      background: var(--red-light);
      color: var(--red);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.2rem;
      font-weight: 700;
      transition: transform 0.3s;
      flex-shrink: 0;
    }
    .accordion-item.active .accordion-icon { transform: rotate(45deg); background: var(--red); color: var(--white); }

    .accordion-body {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.4s ease, padding 0.4s ease;
    }
    .accordion-item.active .accordion-body {
      max-height: 250px;
      padding: 0 1.5rem 1.5rem;
    }
    .accordion-body p {
      color: var(--gray-700);
      line-height: 1.7;
    }

    /* ===== Get Involved ===== */
    .get-involved { background: var(--white); }

    .cards-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 2rem;
      margin-top: 2.5rem;
    }
    .card {
      background: var(--gray-50);
      border: 1px solid var(--gray-200);
      border-radius: 12px;
      padding: 2rem;
      text-align: center;
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .card:hover { transform: translateY(-4px); box-shadow: 0 8px 30px rgba(0,0,0,0.08); }

    .card-icon {
      width: 56px;
      height: 56px;
      border-radius: 50%;
      background: var(--red-light);
      color: var(--red);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.5rem;
      margin: 0 auto 1.25rem;
    }
    .card h3 { margin-bottom: 0.75rem; color: var(--navy); }
    .card p { color: var(--gray-700); font-size: 0.95rem; line-height: 1.6; margin-bottom: 1.5rem; }

    /* ===== News Carousel ===== */
    .news { background: var(--gray-50); border-top: 1px solid var(--gray-200); }

    .carousel-wrap { position: relative; margin-top: 2.5rem; }

    .carousel-track-wrap {
      overflow: hidden;
      border-radius: 12px;
    }

    .carousel-track {
      display: flex;
      transition: transform 0.5s ease;
    }

    .news-card {
      flex: 0 0 calc(33.333% - 1.33rem);
      min-width: calc(33.333% - 1.33rem);
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: 10px;
      padding: 1.5rem;
      margin-right: 2rem;
    }

    .news-tag {
      display: inline-block;
      font-size: 0.72rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      background: var(--red-light);
      color: var(--red);
      padding: 0.3rem 0.7rem;
      border-radius: 4px;
      margin-bottom: 0.75rem;
    }
    .news-card h4 {
      font-size: 1.05rem;
      font-weight: 700;
      color: var(--navy);
      margin-bottom: 0.5rem;
      line-height: 1.35;
    }
    .news-card p {
      font-size: 0.9rem;
      color: var(--gray-700);
      line-height: 1.55;
    }

    .carousel-btns {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 1rem;
      margin-top: 1.5rem;
    }
    .carousel-btn {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      border: 2px solid var(--gray-300);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.2rem;
      color: var(--navy);
      transition: all 0.2s;
    }
    .carousel-btn:hover:not(:disabled) {
      background: var(--navy);
      border-color: var(--navy);
      color: var(--white);
    }
    .carousel-btn:disabled {
      opacity: 0.35;
      cursor: default;
    }
    .carousel-dots {
      display: flex;
      gap: 0.5rem;
    }
    .carousel-dot {
      width: 10px;
      height: 10px;
      border-radius: 50%;
      background: var(--gray-300);
      transition: background 0.2s;
    }
    .carousel-dot.active { background: var(--red); }

    /* ===== Donate CTA Section ===== */
    .donate-cta {
      background: linear-gradient(135deg, var(--red) 0%, var(--red-dark) 100%);
      color: var(--white);
    }
    .donate-cta h2 { color: var(--white); }
    .donate-cta .section-label { color: rgba(255,255,255,0.8); }

    .donate-body-text {
      font-size: 1.05rem;
      opacity: 0.9;
      max-width: 600px;
      line-height: 1.7;
      margin-bottom: 2.5rem;
    }

    .impact-table {
      width: 100%;
      max-width: 750px;
      border-collapse: collapse;
      margin-bottom: 2.5rem;
    }
    .impact-table th, .impact-table td {
      padding: 1rem 1.25rem;
      text-align: left;
      border-bottom: 1px solid rgba(255,255,255,0.2);
      font-size: 0.95rem;
    }
    .impact-table th {
      font-size: 0.75rem;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      opacity: 0.7;
    }
    .impact-table tr:last-child td { border-bottom: none; }
    .impact-table .amount { font-weight: 800; font-size: 1.15rem; white-space: nowrap; }
    .impact-table .custom-row td { padding-top: 0.5rem; opacity: 0.75; font-style: italic; }

    .btn-donate-large {
      background: var(--white);
      color: var(--red);
      padding: 1rem 2.5rem;
      font-size: 1.1rem;
      font-weight: 800;
      border-radius: 8px;
    }
    .btn-donate-large:hover { background: var(--gray-100); }

    /* ===== Footer ===== */
    .footer {
      background: var(--navy);
      color: var(--white);
      padding: 4rem 0 2rem;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 3rem;
      margin-bottom: 3rem;
    }
    .footer-col h4 {
      font-size: 0.82rem;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: rgba(255,255,255,0.5);
      margin-bottom: 1.25rem;
    }
    .footer-col a {
      display: block;
      font-size: 0.9rem;
      color: rgba(255,255,255,0.75);
      padding: 0.25rem 0;
      transition: color 0.2s;
    }
    .footer-col a:hover { color: var(--white); }

    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.1);
      padding-top: 2rem;
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 1rem;
      font-size: 0.85rem;
      color: rgba(255,255,255,0.5);
    }
    .footer-social {
      display: flex;
      gap: 1rem;
    }
    .footer-social a {
      color: rgba(255,255,255,0.5);
      font-size: 1.1rem;
      transition: color 0.2s;
    }
    .footer-social a:hover { color: var(--white); }

    /* ===== Donate Modal ===== */
    .modal-overlay {
      position: fixed;
      inset: 0;
      z-index: 2000;
      background: rgba(0,0,0,0.6);
      display: flex;
      align-items: center;
      justify-content: center;
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.3s;
    }
    .modal-overlay.active {
      opacity: 1;
      pointer-events: auto;
    }

    .modal {
      background: var(--white);
      border-radius: 16px;
      padding: 2.5rem;
      max-width: 520px;
      width: 90%;
      max-height: 90vh;
      overflow-y: auto;
      position: relative;
    }

    .modal-close {
      position: absolute;
      top: 1rem;
      right: 1rem;
      width: 36px;
      height: 36px;
      border-radius: 50%;
      background: var(--gray-100);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.2rem;
      color: var(--gray-700);
      transition: background 0.2s;
    }
    .modal-close:hover { background: var(--gray-200); }

    .modal h3 {
      font-size: 1.5rem;
      color: var(--navy);
      margin-bottom: 0.5rem;
    }
    .modal .modal-sub {
      color: var(--gray-500);
      margin-bottom: 1.5rem;
      font-size: 0.95rem;
    }

    .amount-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 0.75rem;
      margin-bottom: 1.5rem;
    }
    .amount-btn {
      padding: 1rem 0.5rem;
      border: 2px solid var(--gray-200);
      border-radius: 8px;
      font-weight: 800;
      font-size: 1.1rem;
      color: var(--navy);
      transition: all 0.2s;
      text-align: center;
    }
    .amount-btn:hover { border-color: var(--red); color: var(--red); }
    .amount-btn.selected {
      background: var(--red);
      border-color: var(--red);
      color: var(--white);
    }
    .amount-btn.custom-amount {
      grid-column: span 3;
      font-size: 0.9rem;
      font-weight: 600;
      color: var(--gray-500);
      background: var(--gray-50);
    }
    .amount-btn.custom-amount.selected {
      background: var(--red);
      color: var(--white);
    }

    .custom-input-wrap {
      margin-bottom: 1.5rem;
      display: none;
    }
