  <script>
    /* ===== Mobile Menu ===== */
    const hamburger = document.getElementById('hamburger');
    const mobileNav = document.getElementById('mobileNav');

    hamburger.addEventListener('click', () => {
      const isActive = hamburger.classList.toggle('active');
      mobileNav.classList.toggle('active');
      hamburger.setAttribute('aria-expanded', isActive);
    });

    mobileNav.querySelectorAll('a').forEach(link => {
      link.addEventListener('click', () => {
        hamburger.classList.remove('active');
        mobileNav.classList.remove('active');
        hamburger.setAttribute('aria-expanded', 'false');
      });
    });

    function closeMobileMenu() {
      hamburger.classList.remove('active');
      mobileNav.classList.remove('active');
      hamburger.setAttribute('aria-expanded', 'false');
    }

    /* ===== Donate Modal ===== */
    const donateModal = document.getElementById('donateModal');
    let selectedAmount = 25;
    let isCustom = false;

    const impactMessages = {
      25: 'Your $25 provides 5 emergency blankets for displaced families.',
      50: 'Your $50 supplies a family with food and water for one week.',
      100: 'Your $100 funds emergency shelter materials for a household.',
      250: 'Your $250 equips a volunteer with disaster response training.',
      500: 'Your $500 helps deploy a rapid response team to a disaster zone.',
      1000: 'Your $1,000 provides a full month of support for a displaced family.',
      custom: 'Every dollar counts toward saving lives.'
    };

    function openDonateModal() {
      donateModal.classList.add('active');
      document.body.style.overflow = 'hidden';
    }

    function closeDonateModal() {
      donateModal.classList.remove('active');
      document.body.style.overflow = '';
    }

    donateModal.addEventListener('click', (e) => {
      if (e.target === donateModal) closeDonateModal();
    });

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && donateModal.classList.contains('active')) {
        closeDonateModal();
      }
    });

    function selectAmount(btn) {
      document.querySelectorAll('.amount-btn').forEach(b => b.classList.remove('selected'));
      btn.classList.add('selected');
      const val = btn.dataset.amount;

      if (val === 'custom') {
        isCustom = true;
        document.getElementById('customInputWrap').classList.add('visible');
        const customVal = parseInt(document.getElementById('customAmount').value) || 0;
        selectedAmount = customVal;
        updateImpactMessage();
      } else {
        isCustom = false;
        selectedAmount = parseInt(val);
        document.getElementById('customInputWrap').classList.remove('visible');
        updateImpactMessage();
      }
    }

    function updateCustomAmount() {
      if (isCustom) {
        selectedAmount = parseInt(document.getElementById('customAmount').value) || 0;
        updateImpactMessage();
      }
    }

    function updateImpactMessage() {
      const msg = document.getElementById('modalImpact');
      if (isCustom && selectedAmount > 0) {
        msg.textContent = 'Your $' + selectedAmount + ' helps us respond to disasters and support communities in crisis.';
      } else if (isCustom && selectedAmount === 0) {
        msg.textContent = 'Every dollar counts toward saving lives.';
      } else {
        msg.textContent = impactMessages[selectedAmount] || impactMessages['custom'];
      }
    }

    function submitDonation() {
      const amount = isCustom ? selectedAmount : selectedAmount;
      if (isCustom && (!amount || amount < 1)) {
        document.getElementById('customAmount').focus();
        return;
      }
      alert('Thank you for your generous donation of $' + amount + '!\n\nYour support helps us respond to disasters and support communities worldwide.');
      closeDonateModal();
    }

    /* ===== Impact Counters ===== */
    function animateCounters() {
      document.querySelectorAll('.counter').forEach(counter => {
        const target = parseInt(counter.dataset.target);
        const duration = 2000;
        const start = performance.now();

        function update(now) {
          const elapsed = now - start;
          const progress = Math.min(elapsed / duration, 1);
          const eased = 1 - Math.pow(1 - progress, 3);
          const current = Math.floor(eased * target);
          counter.textContent = current.toLocaleString();
          if (progress < 1) requestAnimationFrame(update);
        }

        requestAnimationFrame(update);
      });
    }

    const statsObserver = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          animateCounters();
          statsObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.5 });

    const statsSection = document.querySelector('.impact-stats');
    if (statsSection) statsObserver.observe(statsSection);

    /* ===== Accordion ===== */
    document.querySelectorAll('.accordion-header').forEach(header => {
      header.addEventListener('click', () => {
        const item = header.parentElement;
        const isActive = item.classList.contains('active');

        document.querySelectorAll('.accordion-item').forEach(el => {
          el.classList.remove('active');
          el.querySelector('.accordion-header').setAttribute('aria-expanded', 'false');
        });

        if (!isActive) {
          item.classList.add('active');
          header.setAttribute('aria-expanded', 'true');
        }
      });
    });

    /* ===== News Carousel ===== */
    const track = document.getElementById('carouselTrack');
    const prevBtn = document.getElementById('carouselPrev');
    const nextBtn = document.getElementById('carouselNext');
    const dotsContainer = document.getElementById('carouselDots');
    const cards = track.querySelectorAll('.news-card');
    let currentSlide = 0;
    let slidesPerView = 3;

    function getSlidesPerView() {
      const w = window.innerWidth;
      if (w <= 600) return 1;
      if (w <= 900) return 2;
      return 3;
    }

    function getTotalSlides() {
      return Math.ceil(cards.length / getSlidesPerView());
    }

    function updateCarousel() {
      slidesPerView = getSlidesPerView();
      const cardWidth = track.querySelector('.news-card').offsetWidth;
      const gap = 32;
      const offset = currentSlide * slidesPerView * (cardWidth + gap);
      track.style.transform = 'translateX(-' + offset + 'px)';

      const totalSlides = getTotalSlides();
      prevBtn.disabled = currentSlide === 0;
      nextBtn.disabled = currentSlide >= totalSlides - 1;

      dotsContainer.innerHTML = '';
      for (let i = 0; i < totalSlides; i++) {
        const dot = document.createElement('span');
        dot.className = 'carousel-dot' + (i === currentSlide ? ' active' : '');
        dot.addEventListener('click', () => { currentSlide = i; updateCarousel(); });
        dotsContainer.appendChild(dot);
      }
    }

    prevBtn.addEventListener('click', () => {
      if (currentSlide > 0) { currentSlide--; updateCarousel(); }
    });

    nextBtn.addEventListener('click', () => {
      if (currentSlide < getTotalSlides() - 1) { currentSlide++; updateCarousel(); }
    });

    updateCarousel();
    window.addEventListener('resize', updateCarousel);
  </script>
